package com.secureapp.storage

import java.util.concurrent.atomic.{AtomicBoolean, AtomicReference}
import java.util.concurrent.locks.ReentrantReadWriteLock
import java.security.SecureRandom
import javax.crypto.{Cipher, SecretKey}
import javax.crypto.spec.{GCMParameterSpec, SecretKeySpec}
import java.util.Base64

object EncryptedStorageService {
  private val GCM_TAG_LENGTH = 128
  private val GCM_IV_LENGTH = 12
  private val AES_KEY_LENGTH = 32

  private val masterKey: AtomicReference[SecretKey] = new AtomicReference[SecretKey](null)
  private val keyMaterial: AtomicReference[Array[Byte]] = new AtomicReference[Array[Byte]](null)
  private val isRotating: AtomicBoolean = new AtomicBoolean(false)
  private val shutdownInitiated: AtomicBoolean = new AtomicBoolean(false)
  private val stateLock = new ReentrantReadWriteLock()

  @volatile private var pendingWrites: List[(String, Array[Byte])] = Nil
  @volatile private var ephemeralBuffer: Array[Byte] = new Array[Byte](4096)

  def initialize(keyBytes: Array[Byte]): Unit = {
    require(keyBytes.length == AES_KEY_LENGTH, "Invalid key length")
    stateLock.writeLock().lock()
    try {
      keyMaterial.set(keyBytes.clone())
      masterKey.set(new SecretKeySpec(keyBytes, "AES"))
    } finally {
      stateLock.writeLock().unlock()
    }
  }

  def requestShutdown(): Unit = {
    stateLock.writeLock().lock()
    try {
      shutdownInitiated.set(true)
      performGracefulShutdown()
    } finally {
      stateLock.writeLock().unlock()
    }
  }

  private def performGracefulShutdown(): Unit = {
    // Flush pending writes before clearing key material
    val writes = pendingWrites
    pendingWrites = Nil

    writes.foreach { case (id, data) =>
      flushEncrypted(id, data)
    }

    // Zeroize key material
    zeroizeKeyMaterial()
  }

  def requestKeyRotation(): Unit = {
    stateLock.writeLock().lock()
    try {
      if (!isRotating.compareAndSet(false, true)) return

      try {
        val random = new SecureRandom()
        val newKeyBytes = new Array[Byte](AES_KEY_LENGTH)
        random.nextBytes(newKeyBytes)

        // Store old key reference for re-encryption
        val oldKey = masterKey.get()
        val newKey = new SecretKeySpec(newKeyBytes, "AES")

        // Atomic update: key material and master key together
        keyMaterial.set(newKeyBytes)
        masterKey.set(newKey)

        // Re-encrypt pending writes with new key
        val currentPending = pendingWrites
        pendingWrites = currentPending.map { case (id, data) =>
          val decrypted = decryptWithKey(data, oldKey)
          val reEncrypted = encryptWithKey(decrypted, newKey)
          (id, reEncrypted)
        }
      } finally {
        isRotating.set(false)
      }
    } finally {
      stateLock.writeLock().unlock()
    }
  }

  def encrypt(plaintext: Array[Byte]): Array[Byte] = {
    stateLock.readLock().lock()
    try {
      if (shutdownInitiated.get()) {
        throw new IllegalStateException("Service is shutting down")
      }

      val key = masterKey.get()
      if (key == null) throw new IllegalStateException("Not initialized")
      encryptWithKey(plaintext, key)
    } finally {
      stateLock.readLock().unlock()
    }
  }

  def decrypt(ciphertext: Array[Byte]): Array[Byte] = {
    stateLock.readLock().lock()
    try {
      if (shutdownInitiated.get()) {
        throw new IllegalStateException("Service is shutting down")
      }

      val key = masterKey.get()
      if (key == null) throw new IllegalStateException("Not initialized")
      decryptWithKey(ciphertext, key)
    } finally {
      stateLock.readLock().unlock()
    }
  }

  private def encryptWithKey(plaintext: Array[Byte], key: SecretKey): Array[Byte] = {
    val random = new SecureRandom()
    val iv = new Array[Byte](GCM_IV_LENGTH)
    random.nextBytes(iv)

    val cipher = Cipher.getInstance("AES/GCM/NoPadding")
    val spec = new GCMParameterSpec(GCM_TAG_LENGTH, iv)
    cipher.init(Cipher.ENCRYPT_MODE, key, spec)

    val encrypted = cipher.doFinal(plaintext)
    iv ++ encrypted
  }

  private def decryptWithKey(ciphertext: Array[Byte], key: SecretKey): Array[Byte] = {
    if (ciphertext == null) {
      throw new IllegalArgumentException("Ciphertext must not be null")
    }
    // Must contain at least the IV plus the GCM authentication tag.
    val minLength = GCM_IV_LENGTH + (GCM_TAG_LENGTH / 8)
    if (ciphertext.length < minLength) {
      throw new IllegalArgumentException("Ciphertext is too short to be valid")
    }

    val iv = ciphertext.take(GCM_IV_LENGTH)
    val encrypted = ciphertext.drop(GCM_IV_LENGTH)

    val cipher = Cipher.getInstance("AES/GCM/NoPadding")
    val spec = new GCMParameterSpec(GCM_TAG_LENGTH, iv)
    cipher.init(Cipher.DECRYPT_MODE, key, spec)
    cipher.doFinal(encrypted)
  }

  def queueWrite(id: String, plaintext: Array[Byte]): Unit = {
    val encrypted = encrypt(plaintext)
    stateLock.writeLock().lock()
    try {
      pendingWrites = (id, encrypted) :: pendingWrites
    } finally {
      stateLock.writeLock().unlock()
    }
  }

  private def flushEncrypted(id: String, data: Array[Byte]): Unit = {
    // Simulate writing to persistent storage
    System.arraycopy(data, 0, ephemeralBuffer, 0, math.min(data.length, ephemeralBuffer.length))
  }

  private def zeroizeKeyMaterial(): Unit = {
    val km = keyMaterial.getAndSet(null)
    if (km != null) {
      java.util.Arrays.fill(km, 0.toByte)
    }
    masterKey.set(null)
    java.util.Arrays.fill(ephemeralBuffer, 0.toByte)
  }

  def getKeyFingerprint(): String = {
    stateLock.readLock().lock()
    try {
      val km = keyMaterial.get()
      if (km == null) return "<no key>"
      val digest = java.security.MessageDigest.getInstance("SHA-256")
      Base64.getEncoder.encodeToString(digest.digest(km.clone()).take(8))
    } finally {
      stateLock.readLock().unlock()
    }
  }
}
